// Owner-role reads of the SPEC-111 demonstration, kept under `_dev` so the ESLint boundary of
// SPEC-101 ET-6 stays the only place allowed to use `serviceDb` in the web app (ADR-0049).
//
// The whole demonstration runs inside `withRollback`: a shared formation, its group with three
// members, two members' personal module progress and streaks, then the limited progress view and the
// active-formation counter. Everything disappears at the end of the request. The invitation code is
// generated by the real repository from an injected deterministic source, so the fixture is stable
// and uses the fixed clock of ADR-0047.
import {
  countActiveFormations,
  createGroup,
  joinGroup,
  listGroupProgress,
  sql,
  type GroupMemberProgress,
} from '@learny/db';
import { asUser, createTestProgramme, createTestUser, withRollback } from '@learny/db/testing';

const FIXED = new Date('2026-11-11T12:20:00Z');
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ23456789';

/** Deterministic source for the demonstration code `LRN-AB23` (ET-2, §10). */
function codeSource(code: string) {
  const suffix = code.slice(4);
  let cursor = 0;
  return () => ALPHABET.indexOf(suffix[cursor++] ?? 'A');
}

export interface Spec111Data {
  /** Fake demonstration code, explicitly labelled as not a real invitation (§10). */
  code: string;
  capacity: { used: number; max: number };
  progress: GroupMemberProgress[];
  /** Active formations of the demonstration owner (owned + active memberships, CL-6). */
  activeCount: number;
}

/** Full demonstration payload; every read is rolled back at the end of the request. */
export async function loadSpec111Demo(): Promise<Spec111Data> {
  return withRollback(async (tx) => {
    const owner = await createTestUser(tx, { firstName: 'Alice' });
    const programme = await createTestProgramme(tx, owner.id, {
      modules: 2,
      chaptersPerModule: 1,
      notionsPerChapter: 1,
      title: 'Programme partagé',
    });
    const [firstModule, secondModule] = programme.moduleIds;
    if (firstModule === undefined || secondModule === undefined) {
      throw new Error('programme de démonstration incomplet');
    }

    const group = await createGroup(tx, {
      formationId: programme.formationId,
      ownerId: owner.id,
      now: FIXED,
      random: codeSource('LRN-AB23'),
    });

    const bob = await createTestUser(tx, { firstName: 'Bob' });
    const carol = await createTestUser(tx, { firstName: 'Carol' });
    await joinGroup(tx, { inviteCode: group.inviteCode, userId: bob.id, now: FIXED });
    await joinGroup(tx, { inviteCode: group.inviteCode, userId: carol.id, now: FIXED });

    // Alice: module 1 validated, module 2 open. Bob: module 1 validated. Carol: no progress yet.
    await tx.execute(sql`
      insert into public.module_progress (user_id, module_id, status, validated_at)
      values (${owner.id}::uuid, ${firstModule}::uuid, 'validated', ${FIXED.toISOString()}::timestamptz)
    `);
    await tx.execute(sql`
      insert into public.module_progress (user_id, module_id, status)
      values (${owner.id}::uuid, ${secondModule}::uuid, 'open')
    `);
    await tx.execute(sql`
      insert into public.module_progress (user_id, module_id, status, validated_at)
      values (${bob.id}::uuid, ${firstModule}::uuid, 'validated', ${FIXED.toISOString()}::timestamptz)
    `);
    await tx.execute(sql`update public.profiles set streak_days = 7 where id = ${bob.id}::uuid`);
    await tx.execute(sql`update public.profiles set streak_days = 3 where id = ${carol.id}::uuid`);

    // The view is read under the owner's JWT: it only returns the groups she belongs to.
    const progress = await asUser(tx, owner.id, (inner) =>
      listGroupProgress(inner, { groupId: group.id }),
    );
    const activeCount = await countActiveFormations(tx, owner.id);

    return {
      code: group.inviteCode,
      capacity: { used: progress.length, max: group.maxMembers },
      progress,
      activeCount,
    };
  });
}
